    """Return True if list elements are monotonically increasing or decreasing."""
    # Check if the list is empty or has only one element
    if len(l) <= 1:
        return True

    # Determine the direction of monotonicity
    increasing = l[1] >= l[0]
    decreasing = l[1] <= l[0]

    # Check if the list is monotonically increasing
    if increasing:
        for i in range(1, len(l)):
            if l[i] < l[i-1]:
                return False

    # Check if the list is monotonically decreasing
    if decreasing:
        for i in range(1, len(l)):
            if l[i] > l[i-1]:
                return False

    # If the list is neither increasing nor decreasing, it is not monotonic
    return False
