    # Base cases
    if n == 0:
        return [1]  # Tri(0) = 1
    elif n == 1:
        return [1, 3]  # Tri(1) = 3, Tri(2) = 2 (1 + 2 / 2)
    elif n == 2:
        return [1, 3, 2]  # Tri(3) = 8 (2 + 3 + 3)

